import assert from "node:assert/strict";
import { default as __ns1_rootMeanSquare } from "./src/root_mean_square.js";
import { default as __ns1_scaledRootMeanSquare } from "./src/scaled_root_mean_square.js";
const ss = Object.freeze({ rootMeanSquare: __ns1_rootMeanSquare, scaledRootMeanSquare: __ns1_scaledRootMeanSquare });
{
{
{
// sqrt((1 + 4 + 9) / 3) * 1e200
        const expected = Math.sqrt(14 / 3) * 1e200;
        const actual = ss.scaledRootMeanSquare([1e200, 2e200, 3e200]);
        assert.equal(Math.abs(actual - expected) / expected < 1e-15, true);
